    print("column-Latin:", column_latin(a))
    print("orthogonal to vertical coordinates:", orthogonal_vertical(a))
if __name__ == "__main__": main()

from typing import List, Tuple
Row = Tuple[int, int, int, int]
def rows(m: int, n: int) -> List[Row]:
    return [(i, (i+1)%m, j, (j+2)%n) for i in range(m) for j in range(n)]
def valid(data: List[Row], m: int, n: int) -> bool:
    target = {(i,j) for i in range(m) for j in range(n)}
    return all({(x[u], x[2+v]) for x in data} == target for u in range(2) for v in range(2))
def main() -> None:
    data = rows(3, 4)
    print("rows:", len(data), "projection condition:", valid(data, 3, 4))
    print(*data[:6], sep="\n")
if __name__ == "__main__": main()

